function statusNotice(title,description,action='',label=title){return `<section class="panel review-confirmation" aria-label="${esc(label)}"><div><strong class="${title==='예상 참여 수 초과'?'point-label':''}">${esc(title)}</strong><p>${esc(description)}</p></div>${action}</section>`}
const screens=[['home','C-02','홈 대시보드'],['editor','C-05','게임 편집기'],['prizes','C-06','경품 설정'],['review','C-08','시안 공유·의견'],['brand-review','B-01','브랜드사 시안'],['publish','C-09','게시·행사 패스'],['operate','C-10','운영 모니터'],['workspace','C-03','브랜드 워크스페이스'],['whitelabel','C-13','화이트라벨'],['report','C-12','성과 리포트 편집'],['brand-report','B-02','브랜드사 성과'],['start','P-01','참여 시작'],['game','P-02','룰렛 게임'],['result','P-03','당첨 결과'],['design','DS','화면 목록·디자인 토큰']];
const state={generated:false,applied:false,consent:false,approved:false,paid:false,published:false,paused:false,ended:false,retried:false,aiReport:false,confirmedReport:false,reportPublished:false,prizeError:false,pass:'basic',filter:'전체',wsTab:'발송 이력',editorTab:'디자인',reportText:'',name:'',mobile:'',color:'#b77ba2',agencyColor:'#6858e8',logo:'STAGEONE',metricVisibility:[true,true,true,true]};
const app=document.getElementById('app');const params=new URLSearchParams(location.search);if(params.get('capture')==='1')document.body.classList.add('capture');
const icon={home:'⌂',events:'▤',workspace:'▧',templates:'◇',whitelabel:'◈'};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}function btn(t,a,cls=''){return `<button class="btn ${cls}" data-action="${a}">${t}</button>`}function route(){return (location.hash.slice(1)||params.get('screen')||'home').split('?')[0]}function go(r){location.hash=r;render()}function toast(t){const n=document.getElementById('toast');n.textContent=t;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2600)}
function navItem(r,t,k){return `<a href="#${r}" class="${route()===r?'active':''}">${icon[k]||'◇'} <span>${t}</span></a>`}
function index(){return `<div class="screen-index"><span>v2.5</span><select id="screen-select" aria-label="화면 선택">${screens.map(([r,id,t])=>`<option value="${r}" ${route()===r?'selected':''}>${id} · ${t}</option>`).join('')}</select><a href="#design">화면 목록</a></div>`}
function shell(body){return `<div class="app-shell" data-frame="Console/1440"><aside class="sidebar"><a class="logo" href="#home"><b class="logo-mark">d.</b><span>두잇킷</span></a><div class="agency">스테이지원 커뮤니케이션</div>${btn('＋ 행사 만들기','new','wide')}<nav class="nav">${navItem('home','홈','home')}${navItem('events','전체 행사','events')}${navItem('workspace','워크스페이스','workspace')}<div class="nav-label">CREATE & SHARE</div>${navItem('templates','게임 템플릿','templates')}${navItem('whitelabel','화이트라벨','whitelabel')}</nav><div class="sidebar-bottom"><div class="plan"><div class="between"><strong>Agency</strong><span class="tag-ai">구독 중</span></div><p class="small dim">브랜드 수 제한 없이<br>모든 행사를 한곳에서.</p><button data-action="usage" class="text-link">구독·사용량 보기 ↗</button></div><div class="user"><div class="avatar">서</div><div>김서연<small><br>프로젝트 매니저</small></div><span class="dim" style="margin-left:auto">⌄</span></div></div></aside><main class="main"><header class="topbar"><span>워크스페이스 <span style="margin:0 10px">/</span> <strong>스테이지원 커뮤니케이션</strong></span><div class="top-actions"><span class="demo-badge">DEMO WORKSPACE</span><button data-action="notifications" aria-label="알림">♧ <span class="tag-ai">3</span></button><div class="avatar">서</div></div></header><div class="content">${body}</div></main></div>${index()}`}
function title(eyebrow,h,p,action=''){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${h}</h1><p class="sub">${p}</p></div>${action}</div>`}function pill(t,k=''){return `<span class="pill ${k}">${t}</span>`}function badge(t='루미에르',k=''){return `<span class="badge ${k}">${t}</span>`}
function steps(active){return `<div class="event-header">${badge()}<h1>루미에르 성수 팝업 룰렛</h1>${pill(state.ended?'종료':state.paused?'일시중지':state.published?'진행 중':'작성 중',state.ended?'ended':'draft')}</div><div class="steps">${[['editor','① 만들기'],['review','② 검토'],['publish','③ 게시'],['operate','④ 운영'],['report','⑤ 리포트']].map(([r,t])=>`<a class="step ${active===r?'active':''}" href="#${r}">${t}</a>`).join('')}</div>`}
const eventData=[['루미에르 성수 팝업 룰렛','루미에르','진행 중','운영','10.12 — 10.16','operate',''],['노바홈 가전박람회 스크래치','노바홈','검토 중','검토','10.20 — 10.22','review','blue'],['그린데이 가을 신제품 퀴즈','그린데이','시작 예정','게시','10.24 — 10.25','publish','green'],['루미에르 뷰티 위크','루미에르','종료','리포트','09.21 — 09.23','report','']];
function eventTable(){return `<div class="table-wrap"><table><thead><tr><th>행사</th><th>상태</th><th>현재 작업</th><th>기간</th><th></th></tr></thead><tbody>${eventData.filter(e=>state.filter==='전체'||e[2]===state.filter).map(e=>`<tr class="clickable" data-go="${e[5]}" ${e[1]!=='루미에르'?'data-example="true"':''}><td><div class="event-cell"><div class="event-icon">${e[1]==='노바홈'?'◇':e[1]==='그린데이'?'✧':'◉'}</div><div><div class="event-name">${e[0]}</div>${badge(e[1],e[6])}</div></div></td><td>${pill(e[2],e[2]==='검토 중'?'review':e[2]==='시작 예정'?'scheduled':e[2]==='종료'?'ended':'')}</td><td class="dim">${e[3]}</td><td class="dim">${e[4]}</td><td class="dim">↗</td></tr>`).join('')}</tbody></table></div>`}
function home(){return shell(`${title('YOUR EVENT DESK','서연님, 오늘도 좋은 행사를 만들어요.','여러 브랜드의 행사, 여기서 한눈에 관리하세요.')}<div class="between mb"><h2>지금 확인할 일 <span class="dim small">3</span></h2><span class="mini-label">마지막 업데이트 방금 전</span></div><div class="tasks"><button class="task" data-go="operate"><div class="task-icon">↗</div><div><strong>발송 실패 확인</strong><small>루미에르 성수 팝업</small></div><b class="count">${state.retried?'0':'5'}</b></button><button class="task" data-go="review"><div class="task-icon">☷</div><div><strong>시안 의견 확인</strong><small>브랜드사 답변을 기다려요</small></div><b class="count">2</b></button><button class="task" data-go="publish"><div class="task-icon">◇</div><div><strong>게시 준비</strong><small>결제와 일정 확인이 필요해요</small></div><b class="count">1</b></button></div><div class="grid home-grid"><section class="panel"><div class="panel-head"><h2>진행 중·예정 행사</h2><a href="#events" class="text-link">전체 보기 ↗</a></div><div class="filters">${['전체','진행 중','검토 중','시작 예정','종료'].map(t=>`<button class="chip ${state.filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div>${eventTable()}</section><aside class="stack"><section class="panel"><h2>이번 달 사용량</h2><div class="stat"><span class="mini-label">행사 패스</span><div class="number">2<span>건 사용</span></div></div><div class="stat"><span class="mini-label">전체 브랜드 발송비</span><div class="number">412,300<span>원</span></div></div><button class="text-link mt" data-action="usage">내역 확인 ↗</button></section><section class="panel"><div class="panel-head"><h2>브랜드 워크스페이스</h2><span class="mini-label">3</span></div>${['루미에르 코스메틱','노바홈','그린데이'].map((t,i)=>`<a class="brand-row" href="#workspace"><div class="brand-symbol" style="${i===1?'background:#eaf1fb;color:#617cad':i===2?'background:#eaf5ed;color:#65886b':''}">${['L','N','G'][i]}</div><div>${t}<small>진행 중 행사 ${i===0?'2':'1'}개</small></div><span class="dim" style="margin-left:auto">›</span></a>`).join('')}</section></aside></div><div class="helper mt"><strong>게임을 만드는 순간부터, 결과를 공유하는 순간까지.</strong>두잇파이브의 게임 템플릿과 경품 발송 연동으로 반복되는 행사 업무를 줄여보세요.</div>`)}
function phone(mode='game',large=false){return `<div class="phone" data-frame="Mobile/390"><div class="phone-notch"></div><div class="phone-body"><div class="lumiere">LUMIÈRE</div>${mode==='result'?`<div class="gift">☕</div><div class="eyebrow" style="color:#b77ba2">A LITTLE GIFT FOR YOU</div><h2>축하합니다!<br>커피 상품권 당첨</h2><p>오늘의 작은 행운을 선물해요.</p><div class="panel" style="text-align:left;padding:20px"><div class="between"><strong class="small">모바일 커피 상품권</strong>${pill('발송 완료')}</div><p class="mt" style="margin-top:15px;margin-bottom:0">${esc(state.mobile||'010-****-1234')}로 발송했습니다.<br>문자 또는 알림톡에서 확인해주세요.</p></div><div class="alert success mt">이 화면은 시연용 가상 발송 결과입니다.</div><button class="phone-button" data-go="brand-report">행사 결과 확인하기</button><p class="mt">루미에르 성수 팝업 · 참여해주셔서 감사합니다.</p>`:mode==='start'?`<h2>당신의 오늘에<br>작은 빛을 더하세요.</h2><p>루미에르 성수 팝업 룰렛 이벤트</p><div class="gift" style="margin:26px auto">✧</div><p>기프트 세트부터 커피 상품권까지<br>룰렛을 돌리고 선물을 만나보세요.</p><input id="participant-name" placeholder="이름" aria-label="이름" value="${esc(state.name)}"><input id="participant-mobile" placeholder="휴대전화 번호" aria-label="휴대전화 번호" value="${esc(state.mobile)}"><label class="checkbox"><input type="checkbox" id="participant-consent">[필수] 이벤트 참여 및 경품 지급을 위한 개인정보 수집·이용에 동의합니다.</label><button class="phone-button" data-action="participate">룰렛 참여하기</button><p style="margin-top:18px">수업 프로젝트 시연용 · 실제 개인정보를 입력하지 마세요.</p>`:`<h2>오늘의 행운을<br>만나보세요.</h2><p>룰렛을 돌려 루미에르의 선물을 받아보세요.</p><div class="pointer">▼</div><div class="wheel" id="roulette"></div><button class="phone-button" data-action="${large?'spin':'preview-spin'}">룰렛 돌리기</button><p style="margin-top:18px">1일 1회 참여 가능 · 경품 소진 시 조기 종료</p>`}</div></div>`}
function editor(prizes=false){const gen=state.generated;return shell(`${steps('editor')}<div class="editor-grid"><div><div class="ai-panel"><div class="between"><h3>✧ AI로 행사 초안 만들기</h3><span class="tag-ai">두잇파이브 템플릿 기반</span></div>${gen?`<p class="small">룰렛 템플릿에 브랜드 색상, 경품, 참여 양식을 반영했어요.</p><div class="inline">${btn(state.applied?'적용 완료':'초안 전체 적용','apply','soft')}${btn('다시 생성','generate','secondary')}<button class="muted-btn" data-action="undo">되돌리기</button></div>`:`<textarea id="prompt" aria-label="행사 설명">10월 성수 팝업 룰렛. 1등 기프트 세트 10개(하루 2개·현장 수령), 2등 커피 상품권 300개, 3등 할인 쿠폰. 이름·전화번호 수집, 브랜드 핑크 톤.</textarea><div class="between mt"><span class="ai-chip">팝업스토어 룰렛</span><span class="ai-chip">박람회 스크래치</span>${btn('✧ 초안 생성','generate')}</div>`}</div><section class="panel"><div class="panel-head"><h2>${prizes?'경품 설정':'게임 편집'}</h2><span class="mini-label">● ${state.applied?'저장됨':'작성 중'}</span></div><div class="editor-tabs">${['디자인','문구','수집·동의','경품','참여 규칙','현장 안내'].map(t=>`<button data-tab="${t}" class="${(prizes?'경품':state.editorTab)===t?'active':''}">${t}</button>`).join('')}</div>${prizes?prizeForm():editorForm()}<div class="between mt"><span class="mini-label">변경 내용은 미리보기에 반영됩니다.</span>${btn('저장하기','save','secondary')}</div></section><div class="between mt"><span class="small dim">${state.consent?'✓ 동의 문구 확인 완료':'동의 문구를 확인하면 시안 공유가 열립니다.'}</span>${btn('시안 검토로 이동 →','to-review')}</div></div><aside class="preview-panel"><div class="preview-head"><span>참여자 화면 미리보기</span><a href="#start">별도 화면 ↗</a></div>${phone()}<span class="preview-caption">모바일 · 루미에르 브랜드 적용</span></aside></div>`)}
function editorForm(){switch(state.editorTab){case '문구':return `<div class="field"><label>이벤트 제목</label><input value="오늘의 행운을 만나보세요."></div><div class="field"><label>참여 안내</label><textarea>룰렛을 돌려 루미에르의 선물을 받아보세요.</textarea></div>`;case '수집·동의':return `<h3>참여자 수집 항목</h3><label class="checkbox"><input type="checkbox" checked>이름</label><label class="checkbox"><input type="checkbox" checked>휴대전화 번호</label><div class="alert">AI 초안 · 담당자 확인이 필요합니다.</div><textarea>이벤트 참여 및 경품 지급을 위해 이름과 휴대전화 번호를 수집합니다. 담당자는 수집 목적·보유 기간·동의 문구를 확인해주세요.</textarea><label class="checkbox"><input type="checkbox" id="consent-check" ${state.consent?'checked':''}>담당자로서 동의 문구를 확인했습니다.</label>`;case '참여 규칙':return `<div class="field"><label>참여 횟수</label><select><option>1일 1회</option><option>행사 기간 1회</option></select></div><div class="field"><label>게임 유형</label><select><option>룰렛 · 즉시 당첨</option><option>스크래치</option></select></div>`;case '현장 안내':return `<div class="field"><label>현장 경품 수령 장소</label><input value="루미에르 성수 팝업 안내 데스크"></div><div class="field"><label>수령 안내</label><textarea>당첨 화면과 코드를 안내 데스크에 보여주세요. 운영 시간 내 현장에서 수령할 수 있습니다.</textarea></div>`;default:return `<div class="alert purple">${state.generated?'✧ AI가 생성한 설정 초안 · ':' '}두잇파이브 룰렛 템플릿 기반</div><div class="field"><label>브랜드 자료 ${state.applied?'<span class="tag-ai">AI 적용</span>':''}</label><div class="input inline"><div class="brand-symbol">L</div><div><strong>루미에르 코스메틱</strong><div class="mini-label">로고·대표 색상 불러옴</div></div><button data-action="brand-load" class="text-link" style="margin-left:auto">다시 불러오기</button></div></div><div class="field"><label>게임 유형</label><select><option>룰렛</option><option>스크래치</option></select></div><div class="field"><label>대표 색상</label><div class="inline"><input type="color" id="brand-color" value="${state.color}" style="width:50px;height:44px;padding:4px"><input value="${state.color}" readonly></div></div><div class="field"><label>행사명</label><input value="루미에르 성수 팝업 룰렛"></div>`}}
function prizeForm(){return `<div class="alert purple">경품 확률·수량·지급 방식을 한곳에서 설정해요.</div><div class="table-wrap"><table><thead><tr><th>경품</th><th>수량</th><th>확률</th><th>지급 방식</th></tr></thead><tbody>${[['기프트 세트','10','0.3','현장 수령'],['커피 상품권','300','9.0','모바일 상품권'],['할인 쿠폰','무제한','30.0','쿠폰 코드']].map((p,i)=>`<tr><td><strong>${i+1}등 ${p[0]}</strong><div class="mini-label">${i===0?'하루 2개 제한':''}</div></td><td>${p[1]}</td><td><input aria-label="${p[0]} 확률" class="probability" value="${p[2]}" style="width:70px;padding:8px"> %</td><td>${p[3]}</td></tr>`).join('')}</tbody></table></div><div class="between mt"><strong>당첨 확률 합계 <span id="prob-total">39.3%</span></strong><span class="dim">꽝 확률 <strong id="prob-none">60.7%</strong></span></div><div id="prob-error" class="alert mt" hidden>확률 합계가 100%를 초과했습니다. 저장할 수 없습니다.</div>`}
function review(){return shell(`${steps('review')}<div class="grid cols-2"><section class="panel"><div class="panel-head"><h2>브랜드사와 시안 확인하기</h2>${pill(state.approved?'확정됨':'검토 중','review')}</div><p class="sub">링크 하나로 시안을 공유하고, 수정 의견을 모으세요.</p><div class="field"><label>브랜드사 미리보기 링크</label><div class="inline"><input readonly value="stageone.서비스도메인/lumiere/preview">${btn('링크 복사','copy-review','secondary')}</div></div><div class="alert purple">접속 비밀번호는 초대 메일에서 확인합니다.<br>확정 전에는 미리보기 버전으로 표시됩니다.</div><div class="between"><span class="small dim">현재 버전 v3 · 마지막 수정 방금 전</span><a class="text-link" href="#brand-review">브랜드사 화면 열기 ↗</a></div><div class="preview-panel mt" style="padding:18px">${phone()}</div></section><section class="panel"><div class="panel-head"><h2>시안 의견 <span class="dim">2</span></h2><span class="mini-label">현재 버전 v3</span></div>${[['박지은','룰렛 색상을 브랜드 핑크로 바꿔주세요.','게임 화면 · 1번 위치'],['박지은','현장 수령 장소를 안내 데스크로 명확히 써주세요.','결과 화면 · 2번 위치']].map((c,i)=>`<div class="comment"><div class="between"><strong>${c[0]} <span class="badge">브랜드사</span></strong><span class="comment-time">오늘 ${i?'11:35':'10:42'}</span></div><p>${c[1]}</p><div class="between"><span class="mini-label">${c[2]}</span><button class="text-link" data-action="resolve">해결로 표시</button></div><input class="mt" placeholder="답변 남기기" aria-label="의견 답변"></div>`).join('')}<div class="alert success mt">${state.approved?'브랜드사가 현재 시안 v3을 확정했습니다.':'시안 확정 기록은 이곳에 표시됩니다.'}</div><div class="between"><span class="mini-label">확정된 버전으로 행사 게시</span>${btn('게시 준비 →','to-publish')}</div></section></div>`)}
function external(body,kind='검토'){return `<main class="external" data-frame="Client/1440"><header class="external-header"><div class="external-logo">${esc(state.logo)} <span class="dim small">COMMUNICATION</span></div><span class="mini-label">루미에르 코스메틱 · ${kind}</span></header><div class="external-content">${body}</div></main>${index()}`}
function brandReview(){return external(`${title('CAMPAIGN PREVIEW','루미에르 성수 팝업 룰렛','시안을 확인하고 의견을 남겨주세요.',btn(state.approved?'시안 확정됨':'현재 시안 확정','approve'))}<div class="grid" style="grid-template-columns:1fr 380px"><div class="preview-panel"><div class="preview-head"><span>미리보기 · 실제 경품이 지급되지 않습니다.</span><span>버전 v3</span></div>${phone()}</div><section class="panel"><h2>시안 의견</h2><p class="sub mt">화면 위치를 선택하고 수정 의견을 남겨주세요.</p><div class="field"><label>의견 위치</label><select><option>게임 화면</option><option>참여 시작</option><option>결과 화면</option></select></div><textarea id="client-comment" placeholder="예: 룰렛 색상을 조금 더 밝게 해주세요."></textarea>${btn('의견 남기기','comment','wide mt')}<div class="comment"><strong>박지은</strong><p>룰렛 색상을 브랜드 핑크로 바꿔주세요.</p><span class="mini-label">게임 화면 · 확인 중</span></div><p class="small dim mt">확정 버튼을 누르면 현재 버전의 승인 기록이 대행사에 전달됩니다.</p></section></div>`)}
function qr(){return '<img class="qr-real" src="participant-qr.svg" alt="루미에르 참여 화면 QR 코드">'}
function publish(){return shell(`${steps('publish')}${state.published?`<div class="alert success">✓ 게시 완료 · 참여 링크가 준비되었습니다. 실제 행사 시작 전에는 시작 예정 상태로 표시됩니다.</div><section class="panel" style="max-width:640px;margin:auto;text-align:center"><h2>이제 참여자를 만나보세요.</h2><p class="sub mt">루미에르 성수 팝업 룰렛</p>${qr()}<p class="mini-label">QR을 스캔하거나 아래 링크로 참여 화면을 열어주세요.</p><div class="inline"><input value="${esc(location.origin+location.pathname+'#start')}" readonly>${btn('복사','copy-participant','secondary')}</div><div class="inline mt" style="justify-content:center"><a class="btn" href="#start">참여 화면 열기 ↗</a><a class="btn secondary" href="#operate">운영 모니터 →</a></div></section>`:`<div class="grid" style="grid-template-columns:1fr 350px"><section class="panel"><h2>행사 패스 선택</h2><p class="sub mt">행사 운영에 맞는 패스를 선택하세요. Agency 할인 20%가 적용됩니다.</p><div class="grid cols-2 mt">${[['basic','기본 행사','312,000','일반 팝업·프로모션','390,000'],['large','대형 행사','712,000','대형 행사·트래픽 대응','890,000']].map(p=>`<button class="pass-card ${state.pass===p[0]?'selected':''}" data-pass="${p[0]}" style="text-align:left"><div class="between"><strong>${p[1]}</strong><span>${state.pass===p[0]?'●':'○'}</span></div><div class="price">${p[2]}<small> 원</small></div><div class="mini-label"><s>${p[4]}원</s> · Agency 할인</div><p class="small dim">${p[3]}</p></button>`).join('')}</div><div class="field"><label>예상 참여 규모</label><input type="number" value="3000" aria-label="예상 참여 규모"></div><div class="alert">예상 참여량을 초과해도 운영은 지속됩니다.<br>초과분은 안내된 구간·단가에 따라 행사 종료 후 정산합니다.</div><div class="field"><label>시안 확정</label><div class="between"><span>${state.approved?'✓ v3 확정 완료':'브랜드사 확정이 필요합니다.'}</span><a href="#brand-review" class="text-link">시안 확인 ↗</a></div></div></section><section class="panel"><h2>비용 미리 확인</h2><div class="cost-row"><span>패스 비용 <span class="tag-ai">확정</span></span><strong>${state.pass==='basic'?'312,000':'712,000'}원</strong></div><div class="cost-row"><span>발송 예상비</span><strong>사용량에 따라 변동</strong></div><div class="cost-row"><span>초과 시 추가비</span><strong>구간·단가 확정 예정</strong></div><p class="small dim">사업제안용 제안가입니다. 실제 결제는 진행되지 않습니다.</p><div class="field"><label>행사 운영 기간</label><div class="input input-muted small">10월 12일 — 10월 16일</div></div><label class="checkbox"><input type="checkbox" id="cost-check">변동 비용과 초과 정산 조건을 확인했습니다.</label>${btn(state.paid?'결제 완료 · 행사 게시':'시연 결제 후 게시','pay','wide')}<p class="small dim mt">시안 확정과 비용 조건 확인 후 게시할 수 있습니다.</p></section></div>`}`)}
function metrics(){const vals=['3,412','2,980','860',state.retried?'100%':'99.4%'];const names=['참여 수','순참여자','당첨 수','발송 성공률'];return names.map((n,i)=>`<div class="panel metric"><span class="metric-name">${n}</span><div class="metric-value">${vals[i]}<span class="small dim">${i===3?'':i===1?' 명':' 건'}</span></div><span class="metric-note">${['누적 게임 참여','중복 참여 제외','현장 경품 포함',state.retried?'854 / 854건 성공':'849 / 854건 성공'][i]}</span></div>`).join('')}
function chart(){return `<div class="chart">${[26,39,68,94,82,48,30,20].map((v,i)=>`<div class="chart-col"><div class="bar" style="height:${v}%"></div><small>${i+10}시</small></div>`).join('')}</div><p class="mini-label" style="margin-top:34px">시간대별 참여 · 가상 데이터</p>`}
function operate(){return shell(`${steps('operate')}<div class="between mb"><div><h2>현장 상황, 한눈에 확인하세요.</h2><p class="sub" style="margin-top:8px">참여부터 경품 지급까지 실시간으로 확인합니다.</p></div><div class="inline">${btn(state.paused?'행사 재개':'일시중지','pause','secondary')}${btn(state.ended?'종료됨':'행사 종료','end','danger')}</div></div>${statusNotice('예상 참여 수 초과','예상 참여 3,000회를 넘어 3,412회가 참여했습니다. 운영은 계속되며, 초과 구간과 추가 정산액은 확정 예정입니다.')}<div class="grid cols-4 mb">${metrics()}</div><div class="grid cols-2"><section class="panel"><div class="panel-head"><h2>시간대별 참여</h2><span class="mini-label">누적 3,412회</span></div>${chart()}</section><section class="panel"><div class="panel-head"><h2>경품 잔여 수량</h2><a href="#prizes" class="text-link">경품 설정 ↗</a></div>${[['기프트 세트','4 / 10개',60,'현장 수령 · 당첨 6명, 수령 6명'],['커피 상품권','52 / 300개',83,'모바일 상품권 자동 발송'],['할인 쿠폰','무제한',30,'쿠폰 코드 지급']].map(p=>`<div class="prize-item"><div class="between"><strong class="small">${p[0]}</strong><span class="small dim">${p[1]}</span></div><div class="progress"><span style="width:${p[2]}%"></span></div><span class="mini-label">${p[3]}</span></div>`).join('')}</section></div><section class="panel mt"><div class="panel-head"><h2>발송 실패 <span style="color:var(--danger)">${state.retried?'0':'5'}</span></h2>${btn('선택 건 재발송','retry','secondary')}</div><div class="table-wrap"><table><thead><tr><th>선택</th><th>참여자</th><th>경품</th><th>실패 사유</th><th>발송 상태</th></tr></thead><tbody>${state.retried?'<tr><td colspan="5" style="text-align:center;color:var(--success)">✓ 재발송이 완료되었습니다. 실패 건이 없습니다.</td></tr>':[1,2,3].map((i)=>`<tr><td><input type="checkbox" checked style="width:auto"></td><td>010-****-${1234+i}</td><td>커피 상품권</td><td class="dim">일시적 발송 오류</td><td><span style="color:var(--danger)">발송 실패</span></td></tr>`).join('')}</tbody></table></div><div class="between mt"><span class="mini-label">모바일 발송 대상 854건 · 현장 당첨 6건 제외</span><a href="#workspace" class="text-link">브랜드 발송 이력 ↗</a></div></section><section class="panel mt"><div class="panel-head"><h2>현장 경품 수령</h2><span class="mini-label">6명 수령 완료 / 당첨자 6명</span></div><div class="inline"><input id="claim-code" placeholder="당첨 코드 또는 전화번호 뒷자리"><button class="btn secondary" data-action="claim">당첨자 조회</button></div></section>`)}
function workspace(){return shell(`${title('BRAND WORKSPACE','루미에르 코스메틱','이 브랜드의 행사와 데이터, 발송 이력을 따로 관리합니다.',badge('브랜드별 분리'))}<div class="editor-tabs">${['행사','발송 이력','브랜드 자료','게스트'].map(t=>`<button data-wstab="${t}" class="${state.wsTab===t?'active':''}">${t}</button>`).join('')}</div>${state.wsTab==='행사'?`<section class="panel">${eventTable()}</section>`:state.wsTab==='브랜드 자료'?`<section class="panel" style="max-width:680px"><h2>브랜드 기본 자료</h2><div class="field"><label>로고</label><div class="input lumiere">LUMIÈRE</div></div><div class="field"><label>대표 색상</label><input type="color" value="${state.color}" style="width:60px;height:45px"></div>${btn('저장','save')}</section>`:state.wsTab==='게스트'?`<section class="panel"><h2>브랜드사 게스트</h2><div class="inline mt"><input placeholder="이메일 주소" aria-label="초대 이메일">${btn('초대 미리보기','invite')}</div><div class="comment"><strong>박지은</strong><p>j***@lumiere.example · 시안·성과 열람</p><button class="text-link" data-action="password">접속 비밀번호 재발급</button></div></section>`:`<div class="grid cols-3 mb">${[['이번 달 발송 건수','1,240','여러 루미에르 행사 합계'],['이번 달 발송비','86,500원','이 브랜드 발송 비용만 집계'],['브랜드 행사','3건','참여 데이터·권한 분리']].map(x=>`<div class="panel metric"><span class="metric-name">${x[0]}</span><div class="metric-value">${x[1]}</div><span class="metric-note">${x[2]}</span></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>발송 이력</h2>${btn('월별 내역 CSV','csv','secondary')}</div><div class="table-wrap"><table><thead><tr><th>행사</th><th>채널</th><th>발송 건수</th><th>발송비</th><th>상태</th></tr></thead><tbody><tr><td>루미에르 성수 팝업 룰렛</td><td>상품권·알림톡</td><td>854건</td><td>행사별 정산 예정</td><td>${pill('집계 중')}</td></tr><tr><td>루미에르 뷰티 위크</td><td>쿠폰·문자</td><td>386건</td><td>월 합계에 포함</td><td>${pill('완료')}</td></tr></tbody></table></div><div class="alert purple mt">현재 워크스페이스: 루미에르 코스메틱<br>다른 브랜드의 참여자·발송 이력은 이 화면에 표시되지 않습니다.</div></section>`}`)}
function whitelabel(){return shell(`${title('YOUR BRAND, YOUR CLIENT','대행사 이름으로 공유하세요.','클라이언트가 보는 모든 화면에 우리의 브랜드를 담습니다.')}<div class="grid cols-2"><section class="panel"><h2>브랜딩</h2><div class="field"><label>대행사 이름</label><input value="스테이지원 커뮤니케이션"></div><div class="field"><label>로고 워드마크</label><input id="agency-logo" value="${esc(state.logo)}"></div><div class="field"><label>대표 색상</label><input id="agency-color" type="color" value="${state.agencyColor}" style="width:65px;height:45px"></div>${btn('브랜딩 저장','brand-save')}<details class="mt"><summary class="small dim" style="cursor:pointer">고급 설정 · 도메인·메일</summary><div class="field"><label>브랜드사 화면 주소</label><input value="stageone.서비스도메인/lumiere"></div><div class="field"><label>참여자 링크 주소</label><input value="play.서비스도메인/lumiere"></div><div class="alert">소유 도메인 연결 · 확인 중 (목업 상태)</div><div class="field"><label>초대 메일 제목</label><input value="스테이지원에서 행사 시안을 공유했습니다."></div><p class="mini-label">도메인과 메일은 실제 연결되지 않습니다.</p></details></section><section class="panel"><div class="panel-head"><h2>고객 화면 미리보기</h2><a href="#brand-report" class="text-link">고객 화면으로 보기 ↗</a></div><div style="border:1px solid var(--line);border-radius:10px;overflow:hidden"><div style="background:#fafbfc;padding:12px;font-size:10px;color:#9da2ad">● ● ●　stageone.서비스도메인/lumiere</div><div style="padding:28px"><div class="external-logo" style="color:${state.agencyColor}">${esc(state.logo)}</div><h2 class="mt">루미에르 성수 팝업</h2><p class="small dim">행사 성과 리포트</p><div class="grid cols-2"><div class="input"><span class="mini-label">참여 수</span><h1 style="margin-top:10px">3,412</h1></div><div class="input"><span class="mini-label">발송 성공률</span><h1 style="margin-top:10px">99.4%</h1></div></div>${chart()}</div></div><p class="small dim mt">고객 화면·참여자 화면·PDF에는 두잇킷 로고가 표시되지 않습니다.</p></section></div><section class="panel mt"><div class="panel-head"><h2>시작 가이드</h2><span class="mini-label">3 / 5 완료</span></div><div class="inline" style="flex-wrap:wrap">${['✓ 브랜딩 설정','✓ 브랜드 추가','✓ 행사 만들기','○ 게스트 초대','○ 고객 화면 확인'].map(t=>`<span class="chip">${t}</span>`).join('')}</div></section>`)}
function report(){return shell(`${steps('report')}<div class="grid" style="grid-template-columns:minmax(0,1fr) 430px"><section class="panel"><div class="panel-head"><h2>성과 리포트 작성</h2>${pill(state.ended?'최종 리포트':'중간 리포트','review')}</div><h3>공개 지표</h3><div class="grid cols-2">${['참여 수','순참여자','당첨 수','발송 성공률'].map((t,i)=>`<label class="checkbox"><input type="checkbox" data-metric="${i}" ${state.metricVisibility[i]?'checked':''}>${t}</label>`).join('')}</div><div class="ai-panel mt"><div class="between"><h3>✧ AI 결과 요약</h3><span class="tag-ai">집계 데이터 기반</span></div><p class="small dim">AI 초안을 확인한 뒤 직접 수정·확정해주세요.</p>${state.aiReport?`<textarea id="report-text" style="min-height:170px">${esc(state.reportText)}</textarea><div class="between mt"><span class="mini-label">${state.confirmedReport?'✓ 담당자 확정':''}</span>${btn('문장 확정','confirm-report')}</div>`:btn('✧ 요약 초안 생성','ai-report')}<button class="muted-btn mt" data-action="ai-report">다시 생성</button></div><div class="field"><label>공개 시점</label><select id="report-timing"><option>즉시 공개</option><option>행사 종료 후</option><option>지정 일시</option></select></div><div class="inline">${btn('성과 화면 공유','share-report')} ${btn('CSV 내보내기','csv','secondary')} ${btn('PDF 저장','pdf','secondary')}</div><p class="mini-label mt">운영 중에는 중간 리포트, 종료 후에는 최종 리포트로 표시됩니다.</p></section><section class="panel report-preview"><div class="panel-head"><h2>브랜드사 미리보기</h2></div><div class="external-logo">${esc(state.logo)}</div><h2 class="mt">루미에르 성수 팝업</h2><p class="small dim">행사 결과 요약</p><div class="grid cols-2">${['참여 수','순참여자','당첨 수','발송 성공률'].filter((t,i)=>state.metricVisibility[i]).map(t=>`<div class="input"><span class="mini-label">${t}</span><div style="font-weight:800;font-size:22px;margin-top:10px">${{'참여 수':'3,412','순참여자':'2,980','당첨 수':'860','발송 성공률':state.retried?'100%':'99.4%'}[t]}</div></div>`).join('')}</div>${chart()}<p class="small dim">${state.confirmedReport?esc(state.reportText):'확정된 보고문이 여기에 표시됩니다.'}</p></section></div>`)}
function brandReport(){const vals=['3,412','2,980','860',state.retried?'100%':'99.4%'];return external(`${title('CAMPAIGN PERFORMANCE','루미에르 성수 팝업 룰렛','행사 성과 리포트 · 가상 데이터',btn('PDF 다운로드','pdf','secondary'))}<div class="alert purple">${state.ended?'최종 리포트':'중간 리포트'} · 집계 범위: 루미에르 성수 팝업 행사 누적</div><div class="grid cols-4 mb">${['참여 수','순참여자','당첨 수','발송 성공률'].map((t,i)=>state.metricVisibility[i]?`<div class="panel metric"><span class="metric-name">${t}</span><div class="metric-value">${vals[i]}</div><span class="metric-note">${i===3?'모바일 발송 대상 기준':'행사 누적 집계'}</span></div>`:'').join('')}</div><div class="grid" style="grid-template-columns:1.4fr 1fr"><section class="panel"><h2>참여 추이</h2>${chart()}</section><section class="panel"><div class="eyebrow">EVENT HIGHLIGHTS</div><h2>행사 결과 요약</h2><p style="font-size:13px">${esc(state.confirmedReport?state.reportText:'총 3,412회의 게임 참여와 2,980명의 순참여자를 기록했습니다. 경품 당첨은 860건이며, 모바일 경품 발송 성공률은 99.4%입니다.')}</p><div class="export-note">보고문은 시연용 예시입니다. 판매 전환이나 매출 효과를 추정하지 않았습니다.</div></section></div><div class="export-note">Prepared by ${esc(state.logo)} COMMUNICATION · 브랜드사 공유 화면</div>`,'성과 공유')}
function mobile(mode){return `<main class="mobile-outer">${phone(mode,true)}</main>${index()}`}
function design(){return shell(`${title('DESIGN HANDOFF','두잇킷 디자인 보드','화면별 고정 크기 보기와 공통 디자인 토큰을 확인하세요.')}<div class="alert purple">Figma 이전 준비: HTML 텍스트·입력·버튼·표는 개별 요소로 구성했습니다. 화면 전체를 이미지로 합치지 않았습니다.<br>아래 ‘고정 크기’ 링크는 콘솔 1440px / 모바일 390px 보기이며, 현재 웹 목업이 자동으로 Figma 파일을 생성하는 것은 아닙니다.</div><div class="design-grid">${screens.filter(s=>s[0]!=='design').map(([r,id,t])=>`<div class="design-card"><div class="screen-id">${id}</div><h3>${t}</h3><div class="between mt"><a href="#${r}" class="text-link">목업 보기 →</a><a href="?screen=${r}&capture=1" target="_blank" class="mini-label">고정 크기 ↗</a></div></div>`).join('')}</div><section class="panel mt"><h2>공통 디자인 토큰</h2><div class="grid cols-4 mt">${[['Primary','#6858E8'],['Canvas','#F5F6F8'],['Text','#202634'],['Lumière','#B77BA2']].map(x=>`<div class="input"><span class="color-swatch" style="background:${x[1]}"></span><p class="small">${x[0]}<br><span class="dim">${x[1]}</span></p></div>`).join('')}</div><div class="grid cols-3 mt"><div><h3>Typography</h3><p class="small dim">Noto Sans KR<br>제목 28 / 섹션 17 / 본문 14 / 보조 12px</p></div><div><h3>Layout</h3><p class="small dim">Sidebar 224 / Header 72px<br>8px 간격 단위 / 패널 여백 24px</p></div><div><h3>Components</h3><p class="small dim">Button / Status pill / Brand badge<br>Panel / Metric / Input / Event row</p></div></div><div class="inline mt">${btn('디자인 토큰 JSON','tokens','secondary')}${btn('화면 목록 JSON','screen-json','secondary')}</div></section><section class="panel mt"><h2>추천 시연 순서</h2><p class="small dim">홈 → 게임·경품 → 브랜드사 검토 → 게시 → 모바일 참여·당첨 → 운영 → AI 리포트 → 고객 성과 화면</p><p class="small dim">결제·AI 생성·발송은 모두 브라우저 내 가상 동작입니다. 화면 ID와 상태별 컴포넌트를 기준으로 Figma 프레임·오토레이아웃을 구성할 수 있습니다.</p></section>`)}
function events(){return shell(`${title('ALL EVENTS','전체 행사','브랜드와 관계없이 모든 행사를 탐색하세요.',btn('＋ 행사 만들기','new'))}<section class="panel"><div class="filters">${['전체','진행 중','검토 중','시작 예정','종료'].map(t=>`<button data-filter="${t}" class="chip ${state.filter===t?'active':''}">${t}</button>`).join('')}</div>${eventTable()}</section>`)}
function templates(){return shell(`${title('GAME LIBRARY','게임 템플릿','두잇파이브의 게임 자산으로 빠르게 시작하세요.')}<div class="grid cols-3">${[['룰렛','◉','경품 추첨 · 팝업 이벤트'],['스크래치','◇','즉시 당첨 · 프로모션'],['브랜드 퀴즈','?','제품 이해 · 참여 유도']].map(t=>`<section class="panel"><div style="height:180px;background:#f1edfc;display:grid;place-items:center;border-radius:10px;color:#8c7bd0;font-size:68px">${t[1]}</div><h2 class="mt">${t[0]}</h2><p class="small dim">${t[2]}</p>${btn('이 템플릿 사용','template','wide secondary')}</section>`).join('')}</div>`)}
function render(){let r=route();document.body.dataset.screen=r;const map={home,editor:()=>editor(false),prizes:()=>editor(true),review,'brand-review':brandReview,publish,operate,workspace,whitelabel,report,settlement:()=>settlement(),'brand-report':brandReport,start:()=>mobile('start'),game:()=>mobile('game'),result:()=>mobile('result'),design,events,templates};app.innerHTML=(map[r]||home)();document.title=`${screens.find(s=>s[0]===r)?.[2]||(r==='events'?'전체 행사':'홈')} · 두잇킷`;bind();}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('링크를 복사했습니다.')}catch{toast('클립보드 접근이 제한되어 있습니다. 주소를 직접 복사해주세요.')}}
function modal(){app.insertAdjacentHTML('beforeend',`<div class="modal-overlay"><div class="modal"><div class="between"><h2>어느 브랜드의 행사를 만들까요?</h2><button data-action="close" aria-label="닫기">✕</button></div><p class="sub mt">선택한 브랜드의 로고와 색상을 불러옵니다.</p>${['루미에르 코스메틱','노바홈','그린데이'].map((t,i)=>`<button class="brand-choice wide" data-action="choose" style="justify-content:flex-start"><div class="brand-symbol">${['L','N','G'][i]}</div>${t}<span class="dim" style="margin-left:auto">→</span></button>`).join('')}<div class="field"><label>새 브랜드 추가</label><input id="new-brand" placeholder="브랜드 이름"></div>${btn('브랜드 추가 후 시작','add-brand','secondary wide')}</div></div>`);bind();}
function bind(){app.querySelectorAll('[data-go]').forEach(n=>n.onclick=()=>{if(n.dataset.example)toast('다른 브랜드는 목록 예시입니다. 루미에르 행사로 시연합니다.');go(n.dataset.go)});app.querySelectorAll('[data-action]').forEach(n=>n.onclick=()=>action(n.dataset.action,n));app.querySelectorAll('[data-filter]').forEach(n=>n.onclick=()=>{state.filter=n.dataset.filter;render()});app.querySelectorAll('[data-tab]').forEach(n=>n.onclick=()=>{state.editorTab=n.dataset.tab;go(n.dataset.tab==='경품'?'prizes':'editor')});app.querySelectorAll('[data-wstab]').forEach(n=>n.onclick=()=>{state.wsTab=n.dataset.wstab;render()});app.querySelectorAll('[data-pass]').forEach(n=>n.onclick=()=>{state.pass=n.dataset.pass;render()});app.querySelectorAll('[data-metric]').forEach(n=>n.onchange=()=>{state.metricVisibility[+n.dataset.metric]=n.checked;render()});const ss=document.getElementById('screen-select');if(ss)ss.onchange=()=>go(ss.value);const c=document.getElementById('consent-check');if(c)c.onchange=()=>{state.consent=c.checked;toast(c.checked?'동의 문구 확인 완료':'동의 문구 확인이 해제되었습니다.')};const col=document.getElementById('brand-color');if(col)col.oninput=()=>{state.color=col.value;const w=app.querySelector('.wheel');if(w)w.style.background=`conic-gradient(${col.value} 0 60deg,#f8e8f0 60deg 120deg,${col.value} 120deg 180deg,#f8e8f0 180deg 240deg,${col.value} 240deg 300deg,#f8e8f0 300deg)`};app.querySelectorAll('.probability').forEach(n=>n.oninput=()=>{const v=[...app.querySelectorAll('.probability')].reduce((s,n)=>s+(+n.value||0),0);state.prizeError=v>100||v<0;document.getElementById('prob-total').textContent=v.toFixed(1)+'%';document.getElementById('prob-none').textContent=Math.max(0,100-v).toFixed(1)+'%';document.getElementById('prob-error').hidden=!state.prizeError});const rt=document.getElementById('report-text');if(rt)rt.oninput=()=>{state.reportText=rt.value;state.confirmedReport=false};}
function action(a,n){switch(a){case 'new':modal();break;case 'close':document.querySelector('.modal-overlay')?.remove();break;case 'choose':state.generated=false;state.applied=false;state.editorTab='디자인';go('editor');toast('루미에르 시연 행사로 시작합니다.');break;case 'add-brand':if(!document.getElementById('new-brand').value.trim())return toast('브랜드 이름을 입력해주세요.');go('editor');toast('새 브랜드 추가는 가상 시연입니다. 루미에르 템플릿을 열었습니다.');break;case 'generate':n.disabled=true;n.textContent='✧ 초안 생성 중…';setTimeout(()=>{state.generated=true;render();toast('룰렛 초안을 생성했습니다. 적용 전에 확인해주세요.')},650);break;case 'apply':state.applied=true;render();toast('초안을 적용했습니다. 동의 문구를 확인해주세요.');break;case 'undo':state.generated=false;state.applied=false;render();toast('AI 적용 전 상태로 되돌렸습니다.');break;case 'save':toast(state.prizeError?'확률 합계를 수정한 뒤 저장해주세요.':'변경 사항을 저장했습니다.');break;case 'to-review':if(!state.consent){state.editorTab='수집·동의';go('editor');toast('시안 공유 전에 동의 문구를 확인해주세요.')}else go('review');break;case 'approve':state.approved=true;render();toast('현재 시안 v3을 확정했습니다.');break;case 'to-publish':go('publish');break;case 'pay':if(!state.approved)return toast('브랜드사 시안 확정이 필요합니다.');if(!document.getElementById('cost-check').checked)return toast('변동 비용과 초과 정산 조건을 확인해주세요.');state.paid=true;state.published=true;render();toast('시연 결제·게시 완료. 실제 결제는 진행되지 않았습니다.');break;case 'pause':state.paused=!state.paused;render();toast(state.paused?'행사를 일시중지했습니다.':'행사를 재개했습니다.');break;case 'end':state.ended=true;state.paused=false;render();toast('행사를 종료했습니다. 최종 리포트를 작성할 수 있습니다.');break;case 'retry':state.retried=true;render();toast('실패 5건을 가상 재발송했습니다.');break;case 'claim':toast('당첨자: 김*연 · 기프트 세트 · 수령 완료 (시연 데이터)');break;case 'resolve':n.textContent='✓ 해결됨';n.disabled=true;toast('의견을 해결로 표시했습니다.');break;case 'comment':{const t=document.getElementById('client-comment').value.trim();if(!t)return toast('의견을 입력해주세요.');n.insertAdjacentHTML('afterend',`<div class="comment"><strong>박지은</strong><p>${esc(t)}</p><span class="mini-label">방금 전 · 확인 중</span></div>`);document.getElementById('client-comment').value='';toast('시안 의견을 남겼습니다.');break;}case 'copy-review':copy(location.origin+location.pathname+'#brand-review');break;case 'copy-participant':copy(location.origin+location.pathname+'#start');break;case 'brand-save':state.logo=document.getElementById('agency-logo').value||'STAGEONE';state.agencyColor=document.getElementById('agency-color').value;render();toast('브랜딩을 적용했습니다.');break;case 'ai-report':state.aiReport=true;state.confirmedReport=false;state.reportText=`총 3,412회의 게임 참여와 2,980명의 순참여자를 기록했습니다. 경품 당첨은 860건이며, 모바일 경품 ${state.retried?'854건 전체가 발송 완료되었습니다.':'발송 대상 854건 중 849건을 발송해 성공률 99.4%를 기록했습니다. 실패 5건은 재발송 확인이 필요합니다.'} 현장 경품 당첨자 6명은 모두 수령을 완료했습니다.`;render();toast('집계 기반 AI 요약 초안을 생성했습니다.');break;case 'confirm-report':state.reportText=document.getElementById('report-text').value;state.confirmedReport=true;render();toast('보고문을 확정했습니다.');break;case 'share-report':if(state.aiReport&&!state.confirmedReport)return toast('공유 전에 AI 요약 문장을 확정해주세요.');{const t=document.getElementById('report-timing').value;if(t==='행사 종료 후'&&!state.ended)return toast('행사 종료 후 공개로 예약했습니다.');if(t==='지정 일시')return toast('지정 일시 공개는 보조 목업 상태입니다. 즉시 공개를 선택해주세요.');}state.reportPublished=true;go('brand-report');toast('브랜드사 성과 화면을 열었습니다.');break;case 'pdf':window.print();break;case 'csv':download('lumiere-report.csv','\ufeff지표,값\n참여 수,3412\n순참여자,2980\n당첨 수,860\n모바일 발송 대상,854\n발송 성공,'+(state.retried?854:849)+'\n발송 실패,'+(state.retried?0:5)+'\n','text/csv');toast('CSV를 내려받았습니다.');break;case 'participate':{const nm=document.getElementById('participant-name').value.trim(),ph=document.getElementById('participant-mobile').value.trim();if(!nm||!ph)return toast('시연용 이름과 번호를 입력해주세요.');if(!document.getElementById('participant-consent').checked)return toast('필수 동의 항목을 확인해주세요.');state.name=nm;state.mobile=ph.replace(/\d(?=\d{4})/g,'*');go('game');break;}case 'spin':n.disabled=true;n.textContent='행운을 확인하는 중…';document.getElementById('roulette').style.transform='rotate(1470deg)';setTimeout(()=>go('result'),1700);break;case 'preview-spin':document.getElementById('roulette').style.transform='rotate(1470deg)';setTimeout(()=>toast('미리보기: 커피 상품권 당첨 · 실제 발송 없음'),1700);break;case 'template':state.generated=true;go('editor');toast('룰렛 시연 템플릿을 열었습니다.');break;case 'tokens':download('doitkit-design-tokens.json',JSON.stringify({version:'2.5',colors:{primary:'#6858E8',canvas:'#F5F6F8',surface:'#FFFFFF',text:'#202634',muted:'#828895',line:'#E9EBEF',brand:'#B77BA2'},font:{family:'Noto Sans KR',title:28,section:17,body:14,caption:12},spacing:{unit:8,panel:24,content:40},radius:{panel:12,button:8},frames:{console:[1440,960],client:[1440,960],mobile:[390,844]},components:['Button','StatusPill','BrandBadge','Panel','Metric','Input','EventRow']},null,2));break;case 'screen-json':download('doitkit-screen-map.json',JSON.stringify(screens.map(([r,id,name])=>({id,name,url:location.origin+location.pathname+'?screen='+r+'&capture=1',frame:r==='start'||r==='game'||r==='result'?[390,844]:[1440,960]})),null,2));break;case 'usage':toast('Agency 월 290,000원 · 행사 패스 2건 · 발송비 412,300원 (가상 사용량)');break;case 'notifications':toast('발송 실패 5건 · 시안 의견 2건 · 게시 준비 1건');break;case 'invite':toast('초대 메일 미리보기 · 실제 메일은 발송되지 않습니다.');break;case 'password':toast('시연 접속 비밀번호를 재발급했습니다. 실제 메일은 발송되지 않습니다.');break;case 'brand-load':toast('루미에르 로고와 브랜드 색상을 불러왔습니다.');break;}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
